# Stable internal links are relative in every static page, preserving GitHub project-subpath support.
def relative_html(text,route):
 depth=0 if route=='/' else len(route.strip('/').split('/'));prefix='../'*depth
 def repl(m):
  attr,url=m[1],m[2]
  if not url.startswith('/') or url.startswith('//'):return m[0]
  path,sep,frag=url.partition('#');path=path.lstrip('/')
  if not path:path='index.html'
  elif path.endswith('/'):path+='index.html'
  return f'{attr}="{prefix}{path}{sep+frag if sep else ""}"'
 return re.sub(r'(href|src)="([^\"]+)"',repl,text)
